    technicalCoreDesc: "Basado en algoritmos de reconocimiento de movimiento de aprendizaje profundo y mapeo de personajes, capaces de analizar con precisión las características de movimiento en videos y aplicarlas inteligentemente a diferentes modelos de personajes. Ya sean personas reales, personajes de dibujos animados o criaturas fantásticas, todos pueden lograr efectos de sincronización de movimiento perfectos.",
    
    // 案例2 - 运动轨迹控制
    motionTrajectoryControl: "Control de Trayectoria de Movimiento",
    motionTrajectoryControlDesc: "A través de tecnología precisa de control de trayectoria de movimiento, lograr manipulación precisa de movimientos de objetos en videos. El sistema puede analizar y extraer trayectorias de movimiento en videos, luego realizar ajustes y optimizaciones inteligentes según las necesidades del usuario, creando efectos de movimiento fluidos y naturales.",
    dynamicEffectEnhancement: "Mejora de Efectos Dinámicos",
    
    // 案例3 - 角色动作控制
    characterMotionControl: "Control de Movimiento de Personajes",
    characterMotionControlDesc: "A través de tecnología avanzada de captura de movimiento AI, mapea con precisión tus movimientos y expresiones reales a personajes virtuales. El sistema utiliza algoritmos de aprendizaje profundo para analizar en tiempo real las características de movimiento humano, incluyendo movimientos corporales, expresiones faciales, gestos y posturas corporales, luego convierte inteligentemente estos datos en animaciones de personajes. Ya sean personajes de dibujos animados, personas reales o criaturas fantásticas, todos pueden lograr efectos de sincronización de movimiento perfectos. El sistema soporta múltiples métodos de entrada, incluyendo cámara única, arrays de múltiples cámaras, sensores de profundidad, etc., asegurando que se puedan obtener datos de movimiento de alta calidad en diferentes entornos. Al mismo tiempo, los algoritmos de optimización de movimiento integrados pueden corregir automáticamente problemas comunes como vibraciones, ruido, etc., proporcionando efectos de animación estables y fluidos.",
    
    // 动作捕捉输入
    motionCaptureInput: "Entrada de Captura de Movimiento",
    motionCaptureInputDesc: "El sistema utiliza tecnología avanzada de visión por computadora para extraer con precisión datos de movimiento humano de tus videos subidos. Incluye parámetros clave como posiciones articulares, trayectorias de movimiento, cambios de velocidad, etc. Los algoritmos AI pueden reconocer y analizar secuencias de movimiento complejas, como movimientos de baile, artes marciales, comportamientos cotidianos, etc., proporcionando una base de datos de movimiento de alta calidad para la generación posterior de animaciones de personajes. El sistema adopta un flujo de trabajo de procesamiento multi-etapa, asegurando que se puedan obtener datos de movimiento precisos incluso en condiciones de oclusión parcial o iluminación deficiente. Al mismo tiempo, el sistema soporta procesamiento por lotes, puede procesar múltiples archivos de video simultáneamente, mejorando significativamente la eficiencia del trabajo.",
    
    // 角色动作映射
    characterMotionMapping: "Mapeo de Movimiento de Personajes",
    characterMotionMappingDesc: "Runway Act Two mapea inteligentemente los datos de movimiento extraídos a diferentes tipos de personajes virtuales. El sistema Runway Act Two puede manejar varios tipos de personajes, incluyendo personas con diferentes proporciones corporales, personajes de dibujos animados, personajes de animales e incluso criaturas fantásticas. A través de la tecnología avanzada de vinculación esquelética y algoritmos de adaptación de movimiento de Runway Act Two, asegura que los movimientos se vean naturales y fluidos en diferentes personajes, manteniendo al mismo tiempo los detalles y expresividad del movimiento original. El sistema Runway Act Two adopta algoritmos de mapeo adaptativos, capaces de ajustar automáticamente la amplitud y proporción del movimiento según la estructura esquelética y características corporales del personaje.",
    
    // 角色动画输出
    characterAnimationOutput: "Salida de Animación de Personajes",
    characterAnimationOutputDesc: "El sistema AI de Runway Act Two integra profundamente los datos de movimiento procesados con modelos de personajes para generar animaciones de personajes de alta calidad. La salida de Runway Act Two no solo incluye movimientos corporales precisos, sino también cambios naturales de expresiones faciales, detalles de gestos y ajustes de postura corporal. El sistema Runway Act Two utiliza algoritmos avanzados de interpolación y tecnología de procesamiento suave, asegurando la continuidad y naturalidad de la animación, permitiendo que los personajes virtuales muestren un rendimiento de movimiento vívido y natural como personas reales. El sistema Runway Act Two soporta múltiples formatos de salida, incluyendo formatos estándar como FBX, BVH, Alembic, etc., facilitando la integración con software 3D mainstream.",
    
    // 专业光效处理
