    // 实时动作捕捉总结
    realTimeMotionCapture: "La tecnología de captura de movimiento en tiempo real de Runway Act Two te permite controlar directamente personajes virtuales, creando una experiencia interactiva inmersiva. Todo el sistema Runway Act Two adopta una arquitectura de procesamiento de baja latencia, asegurando la respuesta en tiempo real del movimiento. Ya sea desarrollo de juegos, transmisión en vivo virtual, educación y capacitación o producción creativa, Runway Act Two puede proporcionar soluciones de captura de movimiento de nivel profesional. A través de una simple entrada de video, Runway Act Two puede lograr efectos de animación de personajes complejos, reduciendo significativamente las barreras técnicas y costos de la captura de movimiento.",
    
