    // 案例3 - 角色动作控制
    characterMotionControl: "Kontrol Gerakan Karakter",
    characterMotionControlDesc: "Melalui teknologi AI motion capture yang canggih, memetakan gerakan dan ekspresi nyata Anda secara presisi ke karakter virtual. Sistem menggunakan algoritma deep learning untuk menganalisis karakteristik gerakan manusia secara real-time, termasuk gerakan tubuh, ekspresi wajah, gestur, dan postur tubuh, kemudian mengubah data ini secara cerdas menjadi animasi karakter. Baik karakter kartun, manusia nyata, atau makhluk fantasi, semuanya dapat mencapai efek sinkronisasi gerakan yang sempurna. Sistem mendukung berbagai metode input, termasuk kamera tunggal, array multi-kamera, sensor kedalaman, dll., memastikan data gerakan berkualitas tinggi dapat diperoleh dalam berbagai lingkungan. Sementara itu, algoritma optimisasi gerakan bawaan dapat secara otomatis memperbaiki masalah umum seperti getaran, noise, dll., memberikan efek animasi yang stabil dan lancar.",
    
    // 动作捕捉输入
    motionCaptureInput: "Input Motion Capture",
    motionCaptureInputDesc: "Sistem menggunakan teknologi computer vision canggih untuk mengekstrak data gerakan manusia secara presisi dari video yang Anda unggah. Termasuk parameter kunci seperti posisi sendi, trajektori gerakan, perubahan kecepatan, dll. Algoritma AI dapat mengenali dan menganalisis urutan gerakan kompleks, seperti gerakan tari, jurus bela diri, perilaku sehari-hari, dll., memberikan dasar data gerakan berkualitas tinggi untuk generasi animasi karakter selanjutnya. Sistem mengadopsi alur kerja pemrosesan multi-tahap, memastikan data gerakan akurat dapat diperoleh bahkan dalam kondisi oklusi parsial atau pencahayaan yang buruk. Sementara itu, sistem mendukung pemrosesan batch, dapat memproses beberapa file video secara bersamaan, sangat meningkatkan efisiensi kerja.",
    
    // 角色动作映射
    characterMotionMapping: "Pemetaan Gerakan Karakter",
    characterMotionMappingDesc: "Runway Act Two memetakan data gerakan yang diekstrak secara cerdas ke berbagai jenis karakter virtual. Sistem Runway Act Two dapat menangani berbagai jenis karakter, termasuk orang dengan proporsi tubuh berbeda, karakter kartun, karakter hewan, bahkan makhluk fantasi. Melalui teknologi skeletal binding canggih dan algoritma adaptasi gerakan Runway Act Two, memastikan gerakan terlihat alami dan lancar pada karakter yang berbeda, sambil mempertahankan detail dan ekspresivitas gerakan asli. Sistem Runway Act Two mengadopsi algoritma pemetaan adaptif, mampu menyesuaikan amplitudo dan proporsi gerakan secara otomatis berdasarkan struktur kerangka dan karakteristik tubuh karakter.",
    
    // 角色动画输出
    characterAnimationOutput: "Output Animasi Karakter",
    characterAnimationOutputDesc: "Sistem AI Runway Act Two mengintegrasikan data gerakan yang diproses secara mendalam dengan model karakter untuk menghasilkan animasi karakter berkualitas tinggi. Output Runway Act Two tidak hanya mencakup gerakan tubuh yang presisi, tetapi juga perubahan ekspresi wajah alami, detail gestur, dan penyesuaian postur tubuh. Sistem Runway Act Two menggunakan algoritma interpolasi canggih dan teknologi pemrosesan halus, memastikan kontinuitas dan naturalitas animasi, memungkinkan karakter virtual menampilkan performa gerakan yang hidup dan alami seperti manusia nyata. Sistem Runway Act Two mendukung berbagai format output, termasuk format standar seperti FBX, BVH, Alembic, dll., memudahkan integrasi dengan software 3D mainstream.",
    
    // 专业光效处理
    professionalLightingEffects: "Pemrosesan Efek Cahaya Profesional",
    professionalLightingEffectsDesc: "Runway Act Two menggunakan teknologi pemrosesan cahaya tingkat Hollywood untuk menambahkan efek cahaya profesional ke animasi karakter. Sistem Runway Act Two dapat menganalisis lingkungan scene secara cerdas, secara otomatis menghasilkan skema pencahayaan yang sesuai, termasuk sumber cahaya utama, fill light, rim light, dll. Runway Act Two mendukung perubahan sumber cahaya dinamis, efek cahaya volumetrik, lens flare, depth of field blur, color grading, dan efek canggih lainnya. Pemrosesan efek cahaya profesional Runway Act Two ini memberikan animasi karakter kualitas visual tingkat film, sangat meningkatkan daya tarik visual dan profesionalisme karya.",
    
    // 实时动作捕捉总结
    realTimeMotionCapture: "Teknologi motion capture real-time Runway Act Two memungkinkan Anda mengontrol karakter virtual secara langsung, menciptakan pengalaman interaktif yang imersif. Seluruh sistem Runway Act Two mengadopsi arsitektur pemrosesan low-latency, memastikan responsivitas real-time gerakan. Baik pengembangan game, live streaming virtual, pendidikan dan pelatihan, atau produksi kreatif, Runway Act Two dapat memberikan solusi motion capture tingkat profesional. Melalui input video sederhana, Runway Act Two dapat mencapai efek animasi karakter yang kompleks, sangat mengurangi hambatan teknis dan biaya motion capture.",
    
    // 案例4 - 风格迁移展示
    specialEffectsShowcase: "Pameran Transfer Gaya",
    professionalDesignConcept: "Konsep Desain Profesional",
    specialEffectsShowcaseDesc: "Transfer gaya vertikal Runway Act Two yang dioptimalkan untuk perangkat seluler dan media sosial, setiap pameran menampilkan efek transformasi scene karakter yang berbeda. Dari penggantian latar belakang karakter hingga transformasi scene, hingga pameran karakter nyata, Runway Act Two memberikan solusi peningkatan visual tingkat profesional untuk pembuat konten video pendek. Kami berkomitmen untuk memberikan pengalaman visual berkualitas tinggi, melalui desain yang cermat dan kualitas artistik Runway Act Two, menciptakan pengalaman transfer gaya yang cepat dan lancar untuk pengguna, sambil memiliki nilai edukatif yang penting.",
    
