    // 博客页面
    blog: "Blog",
    blogSubtitle: "Jelajahi tren terbaru, tips, dan berbagi kasus transfer gaya AI",
    aiFutureTrends: "Tren Perkembangan Masa Depan Transfer Gaya AI",
    aiTechnology: "Teknologi AI",
    aiFutureDesc1: "Dengan perkembangan pesat teknologi kecerdasan buatan, transfer gaya AI sedang mengalami transformasi yang belum pernah terjadi sebelumnya. Dari keying layar hijau tradisional hingga penggantian latar belakang cerdas berbasis deep learning, dari efek filter sederhana hingga rekonstruksi scene kompleks, teknologi AI sedang mendefinisikan ulang kemungkinan transfer gaya.",
    aiFutureDesc2: "Dalam Runway Act Two, kami memberikan kemampuan generasi transfer gaya AI yang kuat berdasarkan model act one terbaru. Melalui algoritma deep learning, sistem dapat memahami konten video, secara otomatis mengenali foreground dan latar belakang, menghasilkan efek visual berkualitas tinggi. Teknologi ini tidak hanya sangat meningkatkan efisiensi produksi, tetapi juga memberikan lebih banyak ruang kreatif bagi kreator.",
    aiFutureDesc3: "Di masa depan, kami memperkirakan transfer gaya AI akan berkembang ke arah yang lebih cerdas dan personal. Transfer gaya personal, preview efek real-time, dukungan multi-bahasa, dll., akan menjadi konfigurasi standar. Sementara itu, dengan peningkatan kemampuan komputasi, algoritma efek yang lebih kompleks juga akan menjadi layak, memberikan pengalaman visual yang lebih menakjubkan bagi pengguna.",
    aiFutureDesc4: "Kemajuan teknologi tidak hanya tercermin dalam kualitas efek, tetapi juga dalam optimisasi alur kerja. Pemrosesan otomatis yang dibantu AI akan sangat mengurangi intervensi manual, memungkinkan kreator fokus pada ekspresi kreatif daripada detail teknis. Transformasi ini akan mengubah ekosistem industri transfer gaya, membuka pintu produksi efek khusus tingkat profesional untuk lebih banyak kreator.",
    readMore: "Baca Selengkapnya",
    createMovieEffects: "Cara Membuat Efek Film dengan Runway Act Two",
    tutorial: "Tutorial",
    movieEffectsDesc1: "Untuk membuat transfer gaya tingkat profesional, tidak hanya membutuhkan inspirasi kreatif, tetapi juga menguasai alat dan teknik yang benar. Runway Act Two sebagai alat transfer gaya AI berbasis model act one, memberikan kemampuan kreatif yang kuat bagi pengguna. Artikel ini akan menjelaskan secara detail cara menggunakan alat ini untuk membuat efek visual tingkat film.",
    movieEffectsDesc2: "Pertama, persiapan sangat penting. Pastikan materi video Anda berkualitas baik, pencahayaan cukup, latar belakang relatif sederhana. Faktor-faktor ini akan secara langsung mempengaruhi efek pemrosesan AI. Setelah mengimpor video, sistem akan secara otomatis menganalisis konten, mengenali objek foreground dan area latar belakang. Anda dapat mengoptimalkan efek pengenalan dengan menyesuaikan parameter, memastikan pemrosesan tepi lebih presisi.",
    movieEffectsDesc3: "Aplikasi efek adalah inti dari kreativitas. Runway Act Two menyediakan berbagai efek preset, termasuk gaya fiksi ilmiah, scene fantasi, efek aksi, dll. Anda dapat memilih efek yang sesuai sesuai kebutuhan proyek, kemudian menyesuaikan intensitas, warna, animasi, dll., untuk menyesuaikan efek. Pengguna tingkat lanjut juga dapat menggunakan parameter kustom untuk membuat efek visual yang unik.",
    movieEffectsDesc4: "Post-processing juga penting. Setelah aplikasi efek, Anda dapat menggunakan alat color grading bawaan untuk koreksi warna, menambahkan lens flare, efek depth of field, dll. Detail pemrosesan ini akan sangat meningkatkan perasaan profesional dan dampak visual dari karya akhir. Ingat, efek yang baik tidak hanya harus teknis yang kuat, tetapi juga harus melayani ekspresi cerita.",
    creatorShowcase: "Pameran Karya Kreator Unggulan: Pilihan Januari 2024",
    caseStudy: "Berbagi Kasus",
    creatorShowcaseDesc1: "Dalam komunitas kreator Runway Act Two, setiap hari muncul karya-karya menakjubkan. Kreator-kreator ini menggunakan kemampuan kuat teknologi AI untuk mengubah kreativitas menjadi seni visual. Pilihan unggulan kali ini akan menampilkan karya perwakilan dari beberapa kreator unggulan, berbagi pengalaman kreatif dan teknik mereka.",
    creatorShowcaseDesc2: "Kreator Li Ming dari Shanghai menggunakan Runway Act Two untuk membuat film pendek fiksi ilmiah 'Future City'. Dia menggunakan efek AI untuk mengubah jalan kota biasa menjadi scene fiksi ilmiah yang penuh dengan perasaan masa depan, termasuk bangunan melayang, mobil terbang, dan proyeksi hologram. Li Ming berbagi: 'Teknologi AI memungkinkan saya dengan cepat mewujudkan efek visual yang kompleks, sangat mempersingkat siklus produksi. Yang paling penting, ini memungkinkan saya fokus pada ekspresi kreatif, bukan detail teknis.'",
    creatorShowcaseDesc3: "Kreator lain Wang Fang fokus pada efek karakter, karyanya 'Magic Girl' menunjukkan cara mengubah video karakter biasa menjadi scene fantasi yang penuh dengan elemen magis. Melalui penyesuaian parameter yang presisi dan konsep kreatif, dia berhasil menciptakan efek visual yang mimpi, mendapat pujian dari komunitas.",
    creatorShowcaseDesc4: "Karya-karya unggulan ini tidak hanya menunjukkan kemampuan kuat teknologi AI, tetapi juga mencerminkan kreativitas tak terbatas kreator. Setiap kreator mengeksplorasi kombinasi AI dan seni dengan caranya sendiri, membawa kemungkinan baru bagi industri transfer gaya. Kami berharap melihat lebih banyak karya brilian lahir."
    
