    motionCaptureInputDesc: "يستخدم النظام تقنية رؤية الكمبيوتر المتقدمة لاستخراج بيانات حركة الإنسان بدقة من الفيديو الذي تقوم بتحميله. يتضمن المعاملات الرئيسية مثل مواضع المفاصل ومسارات الحركة وتغيرات السرعة وما إلى ذلك. يمكن لخوارزميات الذكاء الاصطناعي التعرف على وتحليل تسلسلات الحركة المعقدة، مثل حركات الرقص وتقنيات الفنون القتالية والسلوكيات اليومية، مما يوفر أساس بيانات حركة عالية الجودة لتوليد الرسوم المتحركة للشخصيات اللاحق. يتبنى النظام خط أنابيب معالجة متعدد المراحل، مما يضمن الحصول على بيانات حركة دقيقة حتى في ظل ظروف الإخفاء الجزئي أو الإضاءة السيئة. في الوقت نفسه، يدعم النظام المعالجة المجمعة، مما يسمح بمعالجة عدة ملفات فيديو في نفس الوقت، مما يحسن بشكل كبير من كفاءة العمل.",
    
