    characterMotionControl: "Управление движениями персонажа",
    characterMotionControlDesc: "С помощью передовых технологий AI-захвата движения точно сопоставляйте ваши реальные движения и выражения с виртуальными персонажами. Система использует алгоритмы глубокого обучения для анализа характеристик движений человеческого тела в реальном времени, включая движения конечностей, мимику, жесты и позы тела, а затем интеллектуально преобразует эти данные в анимацию персонажа. Будь то мультяшные персонажи, реальные люди или фантастические существа, все могут достичь идеального эффекта синхронизации движений. Система поддерживает различные способы ввода, включая одну камеру, массивы нескольких камер, датчики глубины и т.д., обеспечивая получение высококачественных данных о движениях в различных средах. В то же время встроенные алгоритмы оптимизации движений могут автоматически исправлять дрожание, шум и другие распространенные проблемы, обеспечивая стабильные и плавные анимационные эффекты.",
    
