    showcaseDescription: "A través de tecnología avanzada de captura de movimiento AI, mapea con precisión tus movimientos reales a personajes virtuales. Soporta sincronización de movimiento en tiempo real, mapeo multi-personaje, procesamiento profesional de iluminación y otras funciones, proporcionando soluciones profesionales para desarrollo de juegos, transmisiones virtuales, educación y capacitación, y producción creativa.",
    
    // 人物动作同步
    humanMotionSync: "Sincronización de Movimiento Humano",
    humanMotionSyncDesc: "Demuestra cómo sincronizar con precisión los movimientos de una persona real con un personaje virtual. El sistema analiza las características de movimiento en el video original a través de algoritmos de aprendizaje profundo, incluyendo movimientos de extremidades, expresiones faciales y gestos, luego los mapea al modelo de personaje objetivo.",
