    // 奇幻角色同步
    fantasyCharacterSync: "Sincronización de Personajes Fantásticos",
    fantasyCharacterSyncDesc: "Sincroniza movimientos humanos con personajes fantásticos, incluyendo personajes con diferentes proporciones corporales y estructuras esqueléticas. El sistema puede ajustar inteligentemente la amplitud y proporción del movimiento, asegurando que los movimientos se vean naturales y fluidos en diferentes personajes.",
