    professionalDesignConcept: "Concepto de Diseño Profesional",
    specialEffectsShowcaseDesc: "Runway Act Two optimizado específicamente para dispositivos móviles y redes sociales transferencia de estilo vertical, cada demostración presenta diferentes efectos de transformación de escenas de personajes. Desde reemplazo de fondo de personaje hasta transformación de escena y demostración de personas reales, Runway Act Two proporciona a los creadores de videos cortos soluciones profesionales de mejora visual. Nos esforzamos por proporcionar una experiencia visual de alta calidad, a través del diseño cuidadoso y calidad artística de Runway Act Two, creando para los usuarios una experiencia de transferencia de estilo de alta velocidad y fluida, mientras posee importante valor educativo.",
    
