    missionDesc2: "Basándonos en las poderosas capacidades del modelo Runway act one, hemos desarrollado herramientas de transferencia de estilo diseñadas específicamente para usuarios profesionales, haciendo que la producción compleja de efectos especiales sea simple y eficiente.",
